import assert from 'node:assert/strict';
import {readFile} from 'node:fs/promises';
import {pathToFileURL} from 'node:url';
import {resolve} from 'node:path';
const pkg=resolve(process.argv[2]);
const api=await import(pathToFileURL(resolve(pkg,'simple_ffi_web.js')));
await api.default({module_or_path:await readFile(resolve(pkg,'simple_ffi_web_bg.wasm'))});
assert.deepEqual(api.privateRoundTrip({label:'private fields',count:42}),{label:'private fields',count:42});
assert.equal(api.privateLiveCount(),0);
const counter=new api.PrivateCounter(41);
assert.equal(api.privateLiveCount(),1);
assert.throws(()=>api.privateCounterValue(counter,["invalid after cloned handle"]),TypeError);
assert.equal(api.privateCounterValue(counter,[]),41);
assert.equal(counter.increment(),42);
assert.equal(await counter.asyncValue(),42);
counter.free();
assert.equal(api.privateLiveCount(),0);
assert.equal(api.privateCallback({transform(v){return v+1;}}),43);
assert.equal(api.privateId(18446744073709551615n),18446744073709551615n);
assert.deepEqual(api.generatedPrivateRoundTrip({first:'macro one',second:'macro two'}),{first:'macro one',second:'macro two'});
console.log('PASS: private modules/types/fields/functions/objects/callbacks/custom types and dependency-defined legacy macro expansion');
let resolvePending;
assert.equal(await api.privateCancelCallback({wait(){return new Promise(resolve=>{resolvePending=resolve;});}}),true);
resolvePending(77);
await new Promise(resolve=>setTimeout(resolve,0));
console.log('PASS: pending async callback cancellation and late Promise settlement');
let rejectPending;
assert.equal(await api.privateCancelCallback({wait(){return new Promise((_,reject)=>{rejectPending=reject;});}}),true);
rejectPending(new Error('late rejection after cancellation'));
await new Promise(resolve=>setTimeout(resolve,0));
console.log('PASS: canceled callback Promise rejection is observed without double completion');
